// src/component/HomePage.js
import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './HomePage.css';

function HomePage({ user }) {
  const [userEmail, setUserEmail] = useState('');
  const [parkingSlots, setParkingSlots] = useState([]);  // to store parking slots
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  
  const navigate = useNavigate();

  useEffect(() => {
    const storedEmail = localStorage.getItem('userEmail');

    if (user?.email) {
      setUserEmail(user.email);
    } else if (storedEmail) {
      setUserEmail(storedEmail);
    } else {
      navigate('/');
    }
  }, [user, navigate]);

  // Fetch parking slots after confirming user logged in
  useEffect(() => {
    if (userEmail) {
      fetchParkingSlots();
    }
  }, [userEmail]);

  const fetchParkingSlots = async () => {
    setLoading(true);
    setError('');
    try {
      // Update the URL to your actual backend endpoint that returns parking slot data
      const response = await fetch('/api/parking-slots'); 
      if (!response.ok) throw new Error('Failed to fetch parking slots');
      const data = await response.json();
      setParkingSlots(data);
    } catch (err) {
      setError(err.message || 'Error loading parking slots');
    }
    setLoading(false);
  };

  const handleBooking = async (slotId) => {
    try {
      // Call your booking API endpoint for selected parking slot
      const response = await fetch(`/api/parking-slots/${slotId}/book`, {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({email: userEmail})
      });

      if (!response.ok) throw new Error('Booking failed');
      alert('Booking successful!');
      fetchParkingSlots(); // Refresh slots after booking
    } catch (err) {
      alert(err.message || 'Booking error');
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('userEmail');
    navigate('/');
  };

  return (
    <div className="home-container">
      <h1>Welcome to the Parking Slot Booking System</h1>
      {userEmail && <h3>Logged in as: {userEmail}</h3>}
      <button onClick={handleLogout} className="logout-button">Logout</button>

      <hr />

      <h2>Available Parking Slots</h2>

      {loading && <p>Loading parking slots...</p>}
      {error && <p style={{color: 'red'}}>Error: {error}</p>}

      {!loading && !error && parkingSlots.length === 0 && <p>No parking slots available.</p>}

      {!loading && parkingSlots.length > 0 && (
        <ul className="parking-slot-list">
          {parkingSlots.map(slot => (
            <li key={slot.id} className="parking-slot-item">
              <strong>Slot {slot.slotNumber}</strong> - {slot.location} - 
              {slot.booked ? (
                <span style={{color: 'red', marginLeft: 8}}>Booked</span>
              ) : (
                <button onClick={() => handleBooking(slot.id)} className="book-button" style={{marginLeft: 8}}>
                  Book Now
                </button>
              )}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default HomePage;
